// Base64 of the ACORD 25 Certificate of Liability Insurance, used as the
// shared PDF template for BOTH the General Liability and Workers Comp
// generated certificates (ACORD 25 is a single page covering every
// coverage type, each in its own row). Bundled inline (rather than as a
// native asset file) so pdf-lib can load it identically on Android and iOS
// via PDFDocument.load(base64string), with no native asset-folder wiring.
//
// NOTE: this is a real, filled-out certificate (BMB Insulation Inc / Schatz
// & Associates / a real Workers Comp policy). Only the 4 General Liability
// fields (see glPdfFields.ts) and the 4 Workers Comp fields (see
// wcPdfFields.ts) are overwritten per registration; every other field on
// the page — insured name/address, producer contact, certificate # — is
// this vendor's real data and ships unchanged in every generated PDF.
export const ACORD_CERTIFICATE_TEMPLATE_BASE64 =
  '';
